pub struct StepSequence {
    curr: u64,
    step: u64,
    limit: u64,
}

impl Iterator for StepSequence {
    type Item = u64;
    fn next(&mut self) -> Option<Self::Item> {
        if self.curr >= self.limit { return None; }
        let val = self.curr;
        self.curr += self.step;
        Some(val)
    }
}
